INSERT INTO public."seed_meta" (data) VALUES
('{"dataset_name": "child_product_safety_demo_seed", "dataset_version": "0.1.0", "created_at": "2026-06-09", "language": "ko-KR", "data_type": "MOCK", "purpose": "해커톤 시연용 영유아 제품 안전성 룰체커 시드 데이터", "description": "시설, 반, 아동 건강 프로필, 제품 성분, 성분 동의어, 안전 룰셋을 이용해 아동별 제품 사용 가능 여부를 PASS/WARN/FAIL/EXPIRED/UNKNOWN 상태로 확인하기 위한 목업 데이터입니다.", "service_context": {"target_user": "어린이집, 유치원, 보육시설 교사 및 관리자", "main_flow": ["제품 성분표 또는 OCR 결과 입력", "성분명을 표준명으로 정규화", "아동 건강 프로필과 안전 룰셋 비교", "아동별 안전 상태 판정", "교사에게 요약 결과 제공"]}, "coverage": {"child_health_cases": ["특이사항 없음", "우유 알레르기", "계란 알레르기", "땅콩 알레르기", "견과류 알레르기", "민감성 피부", "아토피", "알레르기와 피부 질환 복합 케이스"], "demo_statuses": ["PASS", "WARN", "FAIL", "EXPIRED", "UNKNOWN"], "product_demo_cases": {"PASS": [101], "WARN": [105, 106], "FAIL": [103, 104], "FAIL_AND_WARN": [102, 107], "EXPIRED": [108], "UNKNOWN": [109]}}, "counts": {"facilities": 1, "classrooms": 2, "children": 8, "child_health_profiles": 8, "products": 9, "ingredient_aliases": 18, "safety_rules": 8}, "rule_policy": {"pass_handling": "위험 룰에 매칭되지 않고 유통기한도 유효하면 백엔드에서 PASS로 처리합니다.", "warn_handling": "피부 상태나 민감 성분에 매칭되는 경우 WARN으로 처리합니다.", "fail_handling": "알레르기 성분에 매칭되는 경우 FAIL로 처리합니다.", "expired_handling": "제품 유통기한이 현재 날짜보다 이전이면 EXPIRED로 처리합니다.", "unknown_handling": "성분 목록이 비어 있거나 OCR/파싱 실패 상태이면 UNKNOWN으로 처리합니다."}, "enum_definitions": {"facility_type": ["DAYCARE"], "product_category": ["WET_TISSUE", "LOTION", "CLEANSER", "FOOD", "ETC"], "target_type": ["ALLERGY", "SKIN", "EXPIRY", "UNKNOWN"], "severity": ["PASS", "WARN", "FAIL", "EXPIRED", "UNKNOWN"]}, "validation_notes": ["본 데이터는 실제 제품 안전성을 보장하지 않는 해커톤 시연용 목업 데이터입니다.", "성분 동의어와 안전 룰셋은 시연에 필요한 최소 범위만 포함합니다.", "PASS는 별도 룰로 저장하지 않고, 매칭되는 위험 룰이 없을 때 계산 결과로 생성하는 것을 권장합니다.", "제품 109는 성분표 훼손 또는 OCR 실패 상황을 검증하기 위한 UNKNOWN 전용 케이스입니다."]}'::jsonb);
